package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException;
import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal; import bo.edu.uagrm.saludu.shared.persistence.*; import bo.edu.uagrm.saludu.governance.application.AuditWriter; import bo.edu.uagrm.saludu.governance.domain.AuditOutcome; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/appointment-requests") public class AppointmentAssignmentController {private final JdbcTemplate j;private final DatabaseActorContext c;private final AuditWriter a;public AppointmentAssignmentController(JdbcTemplate j,DatabaseActorContext c,AuditWriter a){this.j=j;this.c=c;this.a=a;}@PostMapping("/{requestId}/assign") @PreAuthorize("hasRole('ADMINISTRATIVE')") @Transactional public LegacyAvailabilityResponse<Map<String,UUID>> assign(@PathVariable UUID requestId,@RequestBody Map<String,Object>b,@AuthenticationPrincipal SessionPrincipal p){Object raw=b.get("slotId");if(!(raw instanceof String s)||s.isBlank())throw new AvailabilityException(400,"Selecciona un cupo para asignar.");UUID slotId=UUID.fromString(s);c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));UUID appointmentId=j.queryForObject("select salud_u.asignar_solicitud_cita(?,?)",UUID.class,requestId,slotId);a.append("APPOINTMENT_REQUEST_ASSIGNED","appointment_request",requestId,AuditOutcome.SUCCESS,Map.of("appointmentId",appointmentId.toString(),"slotId",slotId.toString()));return LegacyAvailabilityResponse.success(Map.of("appointmentId",appointmentId));}}
